questionvariables.text:
/* List of possible questions: 
Question information given as [*sequence*, *monotonicity*, *boundedness*] */
quest_info: rand([
    [{n*(-1)^(n+2)}, "not monotonic", "unbounded"],
    [{log(n/2)}, "monotonic increasing", "bounded below"],[{1/(n+1)}, "monotonic increasing", "bounded below"],
    [{2^(-n+2)}, "monotonic decreasing", "bounded above and below"],  [{1/(n^2+1)}, "monotonic decreasing", "bounded above and below"],
    [{(-1)^n}, "not monotonic", "bounded above and below"], [{(-1)^n + n}, "not monotonic", "bounded above and below"]
]);


/* Separating out question information */
quest_seq: quest_info[1];
ta1: quest_info[2];
ta2: quest_info[3];

/* Model answers for monotonicity and boundedness */
mans1: [
    ["not monotonic", is(ta1="not monotonic")], 
    ["monotonic increasing", is(ta1="monotonic increasing")], 
    ["monotonic decreasing", is(ta1="monotonic decreasing")]
];

mans2: [
    ["unbounded", is(ta2="unbounded")], 
    ["bounded below", is(ta2="bounded below")], 
    ["bounded above", is(ta2="bounded above")], 
    ["bounded above and below", is(ta2="bounded above and below")]
];

/*Worked solution*/
a1:subst(1,n, quest_seq);
a2:subst(2,n, quest_seq);
a3:subst(3,n, quest_seq);
a4:subst(4,n, quest_seq);
